use xiom.io;

use xiom.string;
fn tally_ratings(responses: &Vec[Int]) -> Map[Int, Int] {
  let tally: Map[Int, Int] = Map[Int, Int].new();
  let i = 0;
  while i < responses.len() {
    let r = match responses.get(i) { Some(v) => v, None => 0 };
    let count = match tally.get(&r) { Some(c) => c, None => 0 };
    tally.insert(r, count + 1);
    i = i + 1;
  }
  return tally;
}

fn compute_average(responses: &Vec[Int]) -> Int {
  let total = 0;
  let i = 0;
  while i < responses.len() {
    let r = match responses.get(i) { Some(v) => v, None => 0 };
    total = total + r;
    i = i + 1;
  }
  return total / responses.len();
}

fn main() -> Int {
  let responses: Vec[Int] = Vec[Int].new();
  responses.push(5); responses.push(3); responses.push(4);
  responses.push(5); responses.push(2);

  let tally = tally_ratings(&responses);
  let avg = compute_average(&responses);
  io.println("Average: " + to_string(avg));
  io.println("Total: " + to_string(responses.len()));
  return 0;
